"use client";

import * as React from "react";
import { Dialog as SheetPrimitive } from "@base-ui/react/dialog";
import { cva, type VariantProps } from "class-variance-authority";
import { Icon } from "@iconify/react";

import { cn } from "@/lib/utils";
import { buttonVariants } from "@/components/ui/button";

// Base UI accepts a state function for className; these wrappers merge it with
// cn(), so they take a plain string.
type WithClassName<P> = Omit<P, "className"> & { className?: string };

/** Ink mail Sheet root: a panel that slides in from one edge of the screen. */
const Sheet = SheetPrimitive.Root;

/** The control that opens the sheet. */
const SheetTrigger = SheetPrimitive.Trigger;

/** Closes the sheet. Wrap a Cancel or Done button in it. */
const SheetClose = SheetPrimitive.Close;

/** Moves the sheet to the end of the document body. */
const SheetPortal = SheetPrimitive.Portal;

/** The scrim: a deep black veil with a light blur over the page behind. */
const SheetOverlay = React.forwardRef<
  HTMLDivElement,
  WithClassName<SheetPrimitive.Backdrop.Props>
>(({ className, ...props }, ref) => (
  <SheetPrimitive.Backdrop
    ref={ref}
    data-slot="sheet-overlay"
    className={cn(
      "fixed inset-0 z-50 bg-(--scrim) backdrop-blur-sm",
      "transition-opacity duration-base ease-out",
      "data-[starting-style]:opacity-0 data-[ending-style]:opacity-0",
      className,
    )}
    {...props}
  />
));
SheetOverlay.displayName = "SheetOverlay";

/**
 * Every sheet sits flush against its edge. Only the inner corners round, and
 * a hairline marks the inner side, so the panel reads as the page extended.
 */
const sheetVariants = cva(
  [
    "fixed z-50 flex flex-col gap-4 bg-popover p-6 text-popover-foreground shadow-(--shadow-overlay) outline-none",
    "transition-[translate,opacity] duration-base ease-out",
    "data-[starting-style]:opacity-0 data-[ending-style]:opacity-0",
  ].join(" "),
  {
    variants: {
      side: {
        top: "inset-x-2 top-2 sm:inset-x-3 sm:top-3 max-h-[85vh] rounded-xl border border-border data-[starting-style]:-translate-y-[calc(100%+1rem)] data-[ending-style]:-translate-y-[calc(100%+1rem)]",
        bottom:
          "inset-x-2 bottom-2 sm:inset-x-3 sm:bottom-3 max-h-[85vh] rounded-xl border border-border data-[starting-style]:translate-y-[calc(100%+1rem)] data-[ending-style]:translate-y-[calc(100%+1rem)]",
        left: "inset-y-2 left-2 sm:inset-y-3 sm:left-3 h-auto w-3/4 max-w-sm rounded-xl border border-border data-[starting-style]:-translate-x-[calc(100%+1rem)] data-[ending-style]:-translate-x-[calc(100%+1rem)]",
        right:
          "inset-y-2 right-2 sm:inset-y-3 sm:right-3 h-auto w-3/4 max-w-sm rounded-xl border border-border data-[starting-style]:translate-x-[calc(100%+1rem)] data-[ending-style]:translate-x-[calc(100%+1rem)]",
      },
    },
    defaultVariants: {
      side: "right",
    },
  },
);

interface SheetContentProps
  extends WithClassName<SheetPrimitive.Popup.Props>,
    VariantProps<typeof sheetVariants> {}

/**
 * Ink mail sheet panel: the elevated surface step on the overlay shadow. A
 * bottom sheet carries a short grab handle, and a ghost icon button in the
 * top corner closes any sheet.
 */
const SheetContent = React.forwardRef<HTMLDivElement, SheetContentProps>(
  ({ side = "right", className, children, ...props }, ref) => (
    <SheetPortal>
      <SheetOverlay />
      <SheetPrimitive.Popup
        ref={ref}
        data-slot="sheet-content"
        data-side={side}
        className={cn(sheetVariants({ side }), className)}
        {...props}
      >
        {side === "bottom" && (
          <div
            aria-hidden="true"
            data-slot="sheet-handle"
            className="mx-auto -mt-2 h-1 w-10 shrink-0 rounded-full bg-muted"
          />
        )}
        {children}
        <SheetPrimitive.Close
          data-slot="sheet-close"
          className={cn(
            buttonVariants({ variant: "ghost", size: "icon-sm" }),
            "absolute end-3 top-3",
          )}
        >
          <Icon icon="ph:x" className="size-4" aria-hidden="true" />
          <span className="sr-only">Close</span>
        </SheetPrimitive.Close>
      </SheetPrimitive.Popup>
    </SheetPortal>
  ),
);
SheetContent.displayName = "SheetContent";

/** The title block at the top of a sheet. It leaves room for the close button. */
const SheetHeader = ({
  className,
  ...props
}: React.HTMLAttributes<HTMLDivElement>) => (
  <div
    data-slot="sheet-header"
    className={cn("flex flex-col gap-1.5 pe-8 text-start", className)}
    {...props}
  />
);
SheetHeader.displayName = "SheetHeader";

/** The action row, pinned to the foot of the sheet. */
const SheetFooter = ({
  className,
  ...props
}: React.HTMLAttributes<HTMLDivElement>) => (
  <div
    data-slot="sheet-footer"
    className={cn(
      "mt-auto flex flex-col-reverse gap-2 sm:flex-row sm:justify-end",
      className,
    )}
    {...props}
  />
);
SheetFooter.displayName = "SheetFooter";

/**
 * The sheet title. It renders as an h2, so it sets Inter at medium weight
 * explicitly to stay out of the display serif.
 */
const SheetTitle = React.forwardRef<
  HTMLHeadingElement,
  WithClassName<SheetPrimitive.Title.Props>
>(({ className, ...props }, ref) => (
  <SheetPrimitive.Title
    ref={ref}
    data-slot="sheet-title"
    className={cn(
      "font-sans text-lg font-medium leading-tight tracking-tight text-foreground",
      className,
    )}
    {...props}
  />
));
SheetTitle.displayName = "SheetTitle";

/** The supporting line under the title, in the muted caption ink. */
const SheetDescription = React.forwardRef<
  HTMLParagraphElement,
  WithClassName<SheetPrimitive.Description.Props>
>(({ className, ...props }, ref) => (
  <SheetPrimitive.Description
    ref={ref}
    data-slot="sheet-description"
    className={cn("text-sm text-muted-foreground", className)}
    {...props}
  />
));
SheetDescription.displayName = "SheetDescription";

export {
  Sheet,
  SheetPortal,
  SheetOverlay,
  SheetTrigger,
  SheetClose,
  SheetContent,
  SheetHeader,
  SheetFooter,
  SheetTitle,
  SheetDescription,
};
